"""Text-to-SQL harness: draft -> execute/validate -> optional single repair call.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}
  env.chat(messages, max_tokens=None) -> str     policy calls capped at env.max_calls
  env.schema(db_id) -> str
  env.execute(sql, max_rows=20) -> dict          {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str
  env.prompt(name) -> str
  env.config -> dict
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
LITERAL = re.compile(r"'((?:[^']|'')*)'")
IDENT = re.compile(r"\b([A-Za-z_][A-Za-z_0-9]*)\.([A-Za-z_][A-Za-z_0-9]*)\b")
BARE_CMP = re.compile(
    r"\b([A-Za-z_][A-Za-z_0-9]*)\s*(?:=|!=|<>|\bLIKE\b)\s*'((?:[^']|'')*)'", re.I
)
FROM_JOIN = re.compile(r"\b(?:FROM|JOIN)\s+([A-Za-z_][A-Za-z_0-9]*)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z_0-9]*))?", re.I)
KEYWORDS = {
    "select", "from", "where", "join", "inner", "left", "right", "outer", "on",
    "group", "order", "by", "limit", "as", "and", "or", "not", "in", "is",
    "null", "like", "having", "union", "distinct", "case", "when", "then",
    "else", "end", "asc", "desc", "cross", "natural", "using", "offset",
}
SQL_WORDS = KEYWORDS | {
    "count", "sum", "avg", "min", "max", "cast", "integer", "real", "text",
    "numeric", "blob", "varchar", "char", "int", "float", "double", "date",
    "datetime", "time", "timestamp", "boolean", "true", "false", "between",
    "exists", "all", "any", "some", "with", "recursive", "intersect", "except",
    "values", "ifnull", "coalesce", "nullif", "abs", "round", "length", "lower",
    "upper", "substr", "substring", "trim", "ltrim", "rtrim", "replace", "instr",
    "strftime", "julianday", "date", "time", "datetime", "printf", "format",
    "total", "group_concat", "row_number", "rank", "dense_rank", "over",
    "partition", "rows", "range", "preceding", "following", "unbounded",
    "current", "row", "filter", "collate", "nocase", "binary", "rtrim",
    "escape", "glob", "regexp", "match", "indexed", "temp", "temporary",
    "if", "abort", "fail", "ignore", "rollback", "replace", "conflict",
    "iif", "sign", "random", "hex", "quote", "typeof", "unicode", "char",
    "last_insert_rowid", "changes", "sqlite_version", "soundex", "zeroblob",
    "max", "min", "asc", "desc", "nulls", "first", "last", "window",
}
ENTITY_Q = re.compile(
    r"\b(which|what|show|list|find|give|display|name)\b", re.I
)
ATTR_Q = re.compile(
    r"\b(how many|number of|count|average|avg|mean|sum|total|maximum|minimum|"
    r"most|least|highest|lowest|largest|smallest|longest|shortest|oldest|youngest|"
    r"names?|titles?|ids?|codes?|dates?|years?|ages?|prices?|costs?|amounts?|"
    r"percent(age)?|ratio|rate|score|grade|salary|salaries|revenue|population)\b",
    re.I,
)


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    t = (text or "").strip()
    m = re.search(r"(?is)\b(select|with)\b.*", t)
    if m:
        t = m.group(0)
    return t.rstrip(";").strip()


def _safe_execute(env, sql, max_rows=20):
    try:
        r = env.execute(sql, max_rows=max_rows)
        if isinstance(r, dict):
            return r
    except Exception:
        pass
    return {"ok": False, "columns": [], "rows": [], "n_rows": 0, "error": "execution failed"}


def _table_aliases(sql):
    """alias/table-name -> real table name."""
    out = {}
    for tbl, alias in FROM_JOIN.findall(sql):
        if tbl.lower() in KEYWORDS:
            continue
        out[tbl.lower()] = tbl
        if alias and alias.lower() not in KEYWORDS:
            out[alias.lower()] = tbl
    return out


def _schema_columns(schema):
    """table -> [column names] parsed from CREATE statements (best effort)."""
    cols = {}
    for m in re.finditer(r"CREATE\s+TABLE\s+[`\"]?([A-Za-z_0-9]+)[`\"]?\s*\((.*?)\)\s*;", schema or "", re.S | re.I):
        tbl, body = m.group(1), m.group(2)
        names = []
        depth = 0
        cur = ""
        parts = []
        for ch in body:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        parts.append(cur)
        for p in parts:
            p = p.strip()
            cm = re.match(r"[`\"]?([A-Za-z_][A-Za-z_0-9]*)[`\"]?", p)
            if cm and cm.group(1).lower() not in (
                "primary", "foreign", "unique", "check", "constraint", "key"
            ):
                names.append(cm.group(1))
        cols[tbl.lower()] = (tbl, names)
    return cols


def _strip_noise(sql):
    """Remove string literals and comments so identifier scanning is clean."""
    s = LITERAL.sub("''", sql or "")
    s = re.sub(r"--[^\n]*", " ", s)
    s = re.sub(r"/\*.*?\*/", " ", s, flags=re.S)
    return s


def _check_identifiers(sql, aliases, schema_cols):
    """Flag qualified/bare identifiers that do not exist in the schema."""
    if not schema_cols:
        return []
    s = _strip_noise(sql)
    all_cols = set()
    for _, names in schema_cols.values():
        for n in names:
            all_cols.add(n.lower())
    bad = []
    # qualified references: alias.column / table.column
    for a, c in IDENT.findall(s):
        al, cl = a.lower(), c.lower()
        if c == "*" or al in SQL_WORDS:
            continue
        tbl = aliases.get(al)
        if tbl is None:
            # maybe a table name used directly that we failed to alias-map
            if al in schema_cols:
                tbl = schema_cols[al][0]
            else:
                continue
        tl = tbl.lower()
        if tl not in schema_cols:
            continue
        names = {n.lower() for n in schema_cols[tl][1]}
        if cl not in names:
            bad.append((f"{a}.{c}", tbl, sorted(schema_cols[tl][1])))
    # bare identifiers compared to literals or used in IN lists
    bare_refs = set()
    for m in BARE_CMP.finditer(s):
        start = max(0, m.start() - 60)
        if re.search(r"[A-Za-z_0-9]\.$", s[start:m.start()]):
            continue
        bare_refs.add(m.group(1))
    for m in re.finditer(r"\b([A-Za-z_][A-Za-z_0-9]*)\s+IN\s*\(", s, re.I):
        bare_refs.add(m.group(1))
    for m in re.finditer(r"\b([A-Za-z_][A-Za-z_0-9]*)\s+NOT\s+IN\s*\(", s, re.I):
        bare_refs.add(m.group(1))
    for col in bare_refs:
        cl = col.lower()
        if cl in SQL_WORDS or cl in all_cols:
            continue
        # find tables in the query that could host it
        hosts = []
        for tl in dict.fromkeys(t.lower() for t in aliases.values()):
            if tl in schema_cols:
                hosts.append((schema_cols[tl][0], sorted(schema_cols[tl][1])))
        if hosts:
            bad.append((col, hosts[0][0], hosts[0][1]))
    notes = []
    seen = set()
    for ref, tbl, names in bad:
        if ref.lower() in seen:
            continue
        seen.add(ref.lower())
        notes.append(
            f"- `{ref}` does not exist in the schema. Table {tbl} actually has columns: "
            + ", ".join(names)
            + ". Use the real column names (check the CREATE TABLE / foreign keys); do not invent names."
        )
    return notes[:4]


def _split_top_level(text):
    parts, depth, cur = [], 0, ""
    for ch in text:
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        if ch == "," and depth == 0:
            parts.append(cur)
            cur = ""
        else:
            cur += ch
    parts.append(cur)
    return [p.strip() for p in parts if p.strip()]


def _projection_note(sql, question):
    """Entity-level question but narrow single-column projection -> suggest full rows."""
    q = question or ""
    if not ENTITY_Q.search(q):
        return None
    if ATTR_Q.search(q):
        return None
    s = _strip_noise(sql)
    m = re.search(r"(?is)\bselect\s+(.*?)\bfrom\b", s)
    if not m:
        return None
    head = m.group(1).strip()
    distinct = bool(re.match(r"(?i)distinct\b", head))
    head = re.sub(r"(?i)^distinct\s+", "", head).strip()
    items = _split_top_level(head)
    if len(items) != 1:
        return None
    item = items[0]
    if "*" in item:
        return None
    if re.search(r"(?i)\b(count|sum|avg|min|max|group_concat|total)\s*\(", item):
        return None
    # single plain column (possibly aliased)
    cm = re.match(r"(?i)^(?:[A-Za-z_0-9]+\.)?[`\"]?([A-Za-z_][A-Za-z_0-9]*)[`\"]?(?:\s+(?:as\s+)?[A-Za-z_0-9]+)?$", item)
    if not cm:
        return None
    col = cm.group(1).lower()
    name_like = col in ("name", "title", "names", "country", "city") or col.endswith("name") or col.endswith("_name")
    if not (distinct or name_like):
        return None
    return (
        "- Projection scope: the question asks about entities ('which/show/list ...') without naming specific "
        "attributes, but your query selects only one column. Gold answers for such questions usually return the "
        "FULL rows of the involved tables (e.g. `SELECT *` over the same joins/filters, or `SELECT T1.*` when only "
        "the main entity's own information is asked). Reconsider whether full rows are expected; keep the filters "
        "and joins unchanged."
    )


def _literal_targets(sql, aliases, schema_cols):
    """Map each string literal to candidate (table, column) pairs."""
    targets = {}
    for m in BARE_CMP.finditer(sql):
        col, val = m.group(1), m.group(2)
        # qualified form immediately before?
        start = max(0, m.start() - 60)
        prefix = sql[start:m.start()]
        qm = re.search(r"([A-Za-z_][A-Za-z_0-9]*)\.$", prefix)
        cands = []
        if qm:
            tbl = aliases.get(qm.group(1).lower())
            if tbl:
                cands.append((tbl, col))
        if not cands:
            for tl, (tbl, names) in schema_cols.items():
                for n in names:
                    if n.lower() == col.lower():
                        cands.append((tbl, n))
        if cands:
            targets.setdefault(val, [])
            for c in cands:
                if c not in targets[val]:
                    targets[val].append(c)
    # literals used inside IN (...) lists
    for m in re.finditer(r"([A-Za-z_][A-Za-z_0-9]*(?:\.[A-Za-z_][A-Za-z_0-9]*)?)\s+IN\s*\(([^()]*?)\)", sql, re.I):
        colref, body = m.group(1), m.group(2)
        vals = LITERAL.findall(body)
        if not vals:
            continue
        if "." in colref:
            a, c = colref.split(".", 1)
            tbl = aliases.get(a.lower())
            cands = [(tbl, c)] if tbl else []
        else:
            cands = []
            for tl, (tbl, names) in schema_cols.items():
                for n in names:
                    if n.lower() == colref.lower():
                        cands.append((tbl, n))
        for v in vals:
            targets.setdefault(v, [])
            for c in cands:
                if c not in targets[v]:
                    targets[v].append(c)
    return targets


def _probe_values(env, sql, schema, budget):
    """For each string literal in the draft, show what the column really stores."""
    lits = [v for v in dict.fromkeys(LITERAL.findall(sql)) if v.strip()]
    if not lits:
        return [], budget
    aliases = _table_aliases(sql)
    schema_cols = _schema_columns(schema)
    targets = _literal_targets(sql, aliases, schema_cols)
    notes = []
    for val in lits:
        if budget <= 0:
            break
        cands = targets.get(val) or []
        core = re.sub(r"[%_]", "", val).strip()
        if not core:
            continue
        for tbl, col in cands[:2]:
            if budget <= 0:
                break
            frag = core.split()[0] if core.split() else core
            probe = (
                f'SELECT DISTINCT "{col}" FROM "{tbl}" '
                f"WHERE \"{col}\" LIKE '%{frag}%' LIMIT 8"
            )
            r = _safe_execute(env, probe, max_rows=8)
            budget -= 1
            if not r.get("ok"):
                continue
            vals = [row[0] for row in r.get("rows", []) if row]
            exact = any(isinstance(v, str) and v == val for v in vals)
            if exact and len(vals) == 1:
                continue
            shown = ", ".join(repr(v) for v in vals[:8]) if vals else "(no similar value found)"
            notes.append(
                f"- Column {tbl}.{col}: you filtered on {val!r}. Values actually stored that look related: {shown}."
            )
            break
    return notes, budget


def _probe_empty_join(env, sql, budget):
    """When a join returns nothing, show sample rows of the joined tables."""
    notes = []
    aliases = _table_aliases(sql)
    tables = list(dict.fromkeys(aliases.values()))
    if len(tables) < 2:
        return notes, budget
    for tbl in tables[:3]:
        if budget <= 0:
            break
        r = _safe_execute(env, f'SELECT * FROM "{tbl}" LIMIT 3', max_rows=3)
        budget -= 1
        if r.get("ok") and r.get("rows"):
            cols = ", ".join(str(c) for c in r.get("columns", []))
            rows = "; ".join(str(row) for row in r["rows"][:3])
            notes.append(f"- Sample rows of {tbl} ({cols}): {rows}")
    return notes, budget


def _build_user(task, env, schema):
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\n\nColumn descriptions:\n" + desc.strip()[:2000]
    return user


def solve(task, env):
    cfg = env.config or {}
    schema = env.schema(task["db_id"])
    system = env.prompt("system_prompt.md")
    user = _build_user(task, env, schema)
    messages = [
        {"role": "system", "content": system},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=cfg.get("max_tokens", 800))
    sql = extract_sql(reply)
    if not sql:
        return {"sql": "SELECT 1"}
    if not cfg.get("enable_repair", True):
        return {"sql": sql}

    result = _safe_execute(env, sql)
    ok = bool(result.get("ok"))
    nrows = result.get("n_rows", 0) or 0
    err = result.get("error") or ""

    notes = []
    budget = int(cfg.get("max_probes", 6))
    needs_repair = False

    # --- static checks (catch semantic mistakes even when the query executes) ---
    if cfg.get("check_identifiers", True):
        try:
            aliases = _table_aliases(sql)
            schema_cols = _schema_columns(schema)
            idn = _check_identifiers(sql, aliases, schema_cols)
            if idn:
                needs_repair = True
                notes.extend(idn)
        except Exception:
            pass
    if cfg.get("check_projection", True):
        try:
            pn = _projection_note(sql, task.get("question", ""))
            if pn:
                needs_repair = True
                notes.append(pn)
        except Exception:
            pass

    if not ok:
        needs_repair = True
        notes.append(f"- Your query failed to execute. SQLite error: {err}")
    else:
        if nrows == 0:
            needs_repair = True
            notes.append("- Your query executed but returned ZERO rows. The question expects data, so a filter value, a join key or a condition is probably wrong.")
            if cfg.get("probe_zero_row_joins", True):
                jn, budget = _probe_empty_join(env, sql, budget)
                notes.extend(jn)
            # single-table zero-row queries: show sample rows of the main table too
            if not jn if 'jn' in dir() else True:
                pass
        if cfg.get("probe_literals", True):
            vn, budget = _probe_values(env, sql, schema, budget)
            if vn:
                needs_repair = True
                notes.extend(vn)

    if not needs_repair:
        return {"sql": sql}

    preview = ""
    if ok and nrows:
        preview = (
            f"\nCurrent result columns: {result.get('columns')}\n"
            f"First rows: {result.get('rows', [])[:5]}\n"
        )

    repair_user = (
        user
        + "\n\nYour previous query was:\n```sql\n" + sql + "\n```\n"
        + preview
        + "\nDiagnostics from running it against the real database:\n"
        + "\n".join(notes)
        + "\n\nWrite a corrected query. Use the exact stored values shown above when they reveal a mismatch "
        "(casing, spacing, abbreviation); fix join keys and column names using ONLY names declared in the schema "
        "(never invent column names — inspect the relation's real columns, and for symmetric relations consider "
        "both directions); and make sure the selected columns match exactly what the question asks for (full rows "
        "of the involved tables when it asks 'which/show/list <entities>' without naming attributes). "
        "Keep everything that was already correct. Return only the final query in one ```sql block."
    )
    try:
        reply2 = env.chat(
            [
                {"role": "system", "content": system},
                {"role": "user", "content": repair_user},
            ],
            max_tokens=cfg.get("repair_max_tokens", 700),
        )
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    r2 = _safe_execute(env, sql2)
    if not r2.get("ok"):
        return {"sql": sql}
    if ok and nrows > 0 and (r2.get("n_rows", 0) or 0) == 0:
        return {"sql": sql}
    return {"sql": sql2}

